{"packet_id":"D067-01","doc_id":"D067","jurisdiction":"NJ","category":"security_deposits","lifecycle":"enacted","title":"New Jersey Security Deposit Law","requirement":"A landlord may not take more than one and one-half months' rent as a security deposit, may raise it by no more than 10% a year, and must return it, with interest and an itemized list of deductions, within 30 days after the tenancy ends.","key_value":"1.5 months' rent cap; 10% yearly increase cap; 30-day return","coverage_conditions":"All New Jersey residential rentals where the landlord chooses to collect a deposit; seasonal use or rental of 125 consecutive days or less is exempt from the deposit-holding rules.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Rules apply only if a deposit is collected; 10-or-more-unit landlords have the money-market investment option"},"exemptions":"Seasonal use or rental of not more than 125 consecutive days; seasonal, temporary or migrant farm worker housing is not treated as seasonal use.","penalty":"Tenant may sue for double the amount wrongfully withheld plus court costs and reasonable attorney's fees; where notice or interest is withheld, the tenant may apply the deposit plus 7% annual interest to rent.","effective_date":null,"citation":"N.J.S.A. 46:8-21.2","quoted_span":"The maximum-security deposit to be collected by the landlord cannot be more than one and one-half times one month’s rent ( N.J.S.A. 46:8-21.2 ). It can be less. Any additional yearly security deposit increase may not exceed 10% of the current security deposit.","interaction":null,"confidence":0.75,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D067-01","doc_id":"D067","jurisdiction":"NJ","category":"security_deposits","lifecycle":"enacted","title":"Safe Housing Act security deposit return after domestic-violence lease termination","requirement":"When a tenant ends a lease early under the Safe Housing Act because of domestic violence, the landlord must make the security deposit and interest available within 15 business days and notify the tenant within three business days where to collect it.","key_value":"15 business days","coverage_conditions":"Tenants who terminate a lease under the Safe Housing Act on domestic-violence grounds; the Act does not apply to transient or seasonal rentals.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Domestic-violence lease terminations under the Safe Housing Act"},"exemptions":"Transient or seasonal rentals.","penalty":null,"effective_date":null,"citation":"N.J.S.A. 46:8-9.6","quoted_span":"Within 15 business days after the lease is terminated, the landlord shall make available the return of the tenant’s security deposit, plus any interest earned, to the tenant or the tenant’s agent.","interaction":null,"confidence":0.7,"conflict_flag":false,"conflict_note":null}
